        "visible": true,
        "text": "Growth marketing executive with 13+ years scaling B2B SaaS and consumer tech platforms from series A through post-IPO. Expert in combining brand storytelling with rigorous data-driven performance marketing, product-led expansion loops, and enterprise account-based marketing (ABM). Scaled company annual recurring revenue from $12M to $95M while reducing CAC by 34%.",
